import * as React from "react";
import {Icon,type IconProps} from "@/components/ui/icon";

export type GamepadDirectionalIconProps=Omit<IconProps,"name">;
/** Lucide "gamepad-directional" through the Cojeev Icon: motion presets, sizes and feedback included. */
export function GamepadDirectionalIcon(props:GamepadDirectionalIconProps){return <Icon name="gamepad-directional" {...props}/>;}
